# Let me look for line patterns using basic geometry
from collections import defaultdict
import math

positions = [(r, c) for r in range(24) for c in range(21) if grid[r][c] == 2]

def slope(p1, p2):
    """Returns slope as (dy, dx) reduced fraction"""
    dr = p2[0] - p1[0]
    dc = p2[1] - p1[1]
    if dc == 0:
        return (1, 0)  # vertical
    if dr == 0:
        return (0, 1)  # horizontal
    # Reduce by GCD
    g = math.gcd(abs(dr), abs(dc))
    return (dr//g, dc//g)

# Find all lines that have at least 3 points from our position set
line_to_points = defaultdict(set)

for i, p1 in enumerate(positions):
    for j, p2 in enumerate(positions):
        if i < j:
            m = slope(p1, p2)
            # Check if another point is on this line
            for k, p3 in enumerate(positions):
                if k > j and slope(p1, p3) == slope(p1, p2):
                    line_to_points[m].add((p1[0]*p2[1] - p1[1]*p2[0]))

print(f"Number of unique slope directions: {len([m for m in line_to_points.keys() if len(m) > 0])}")
print(f"Unique line identifiers found: {len(line_to_points)}")

